#################################################################
#    Disjointness Axioms
#################################################################

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:GovernmentBond
        fis:CorporateBond
        fis:MunicipalBond
        fis:SupranationalBond
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:Forward
        fis:Future
        fis:Option
        fis:Swap
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:TreasuryBill
        fis:TreasuryNote
        fis:TreasuryBond
    ) .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption owl:disjointWith fis:EuropeanOption .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:CumulativePreferredStock owl:disjointWith fis:NonCumulativePreferredStock .

fis:GeneralObligationBond owl:disjointWith fis:RevenueBond .

fis:ResidentialMortgageBackedSecurity owl:disjointWith fis:CommercialMortgageBackedSecurity .

fis:SovereignGovernment owl:disjointWith fis:Municipality .

fis:StockExchange owl:disjointWith fis:FuturesExchange .
